-- The 251 Pokémon of Generations 1 and 2: the Pokédex the collection fills.
-- Reference data, so no timestamps and not writable through the API (it's
-- read through views). Written by scripts/pull-pokemon.mjs: names and types
-- from Bulbapedia, the rest from PokéAPI. The artwork is
-- public/pokemon/NNN.webp.

create table pokemon (
  id               integer primary key check (id between 1 and 251),
  name             text not null unique,
  generation       integer not null check (generation in (1, 2)),
  primary_type     text not null check (primary_type in ('normal', 'fire', 'water', 'electric', 'grass', 'ice', 'fighting', 'poison', 'ground', 'flying', 'psychic', 'bug', 'rock', 'ghost', 'dragon', 'dark', 'steel', 'fairy')),
  secondary_type   text check (secondary_type in ('normal', 'fire', 'water', 'electric', 'grass', 'ice', 'fighting', 'poison', 'ground', 'flying', 'psychic', 'bug', 'rock', 'ghost', 'dragon', 'dark', 'steel', 'fairy')),
  category         text not null,
  height_dm        integer not null,
  weight_hg        integer not null,
  entry            text not null,
  -- Pichu (#172) comes before Pikachu (#25), so the check waits for commit.
  evolves_from_id  integer references pokemon (id) deferrable initially deferred,
  evolution_method text,
  check ((evolves_from_id is null) = (evolution_method is null))
);

insert into pokemon (id, name, generation, primary_type, secondary_type, category,
  height_dm, weight_hg, entry, evolves_from_id, evolution_method) values
  (1, 'Bulbasaur', 1, 'grass', 'poison', 'Seed Pokémon', 7, 69, 'The seed on its back is filled with nutrients. The seed grows steadily larger as its body grows.', null, null),
  (2, 'Ivysaur', 1, 'grass', 'poison', 'Seed Pokémon', 10, 130, 'Exposure to sunlight adds to its strength. Sunlight also makes the bud on its back grow larger.', 1, 'Level 16'),
  (3, 'Venusaur', 1, 'grass', 'poison', 'Seed Pokémon', 20, 1000, 'By spreading the broad petals of its flower and catching the sun’s rays, it fills its body with power.', 2, 'Level 32'),
  (4, 'Charmander', 1, 'fire', null, 'Lizard Pokémon', 6, 85, 'The flame on its tail shows the strength of its life force. If it is weak, the flame also burns weakly.', null, null),
  (5, 'Charmeleon', 1, 'fire', null, 'Flame Pokémon', 11, 190, 'It is very hotheaded by nature, so it constantly seeks opponents. It calms down only when it wins.', 4, 'Level 16'),
  (6, 'Charizard', 1, 'fire', 'flying', 'Flame Pokémon', 17, 905, 'If Charizard becomes furious, the flame at the tip of its tail flares up in a light blue shade.', 5, 'Level 36'),
  (7, 'Squirtle', 1, 'water', null, 'Tiny Turtle Pokémon', 5, 90, 'The shell is soft when it is born. It soon becomes so resilient, prodding fingers will bounce off it.', null, null),
  (8, 'Wartortle', 1, 'water', null, 'Turtle Pokémon', 10, 225, 'It is a well-established symbol of longevity. If its shell has algae on it, that Wartortle is very old.', 7, 'Level 16'),
  (9, 'Blastoise', 1, 'water', null, 'Shellfish Pokémon', 16, 855, 'It deliberately makes itself heavy so it can withstand the recoil of the water jets it fires.', 8, 'Level 36'),
  (10, 'Caterpie', 1, 'bug', null, 'Worm Pokémon', 3, 29, 'For protection, it releases a horrible stench from the antennae on its head to drive away enemies.', null, null),
  (11, 'Metapod', 1, 'bug', null, 'Cocoon Pokémon', 7, 99, 'Inside the shell, it is soft and weak as it prepares to evolve. It stays motionless in the shell.', 10, 'Level 7'),
  (12, 'Butterfree', 1, 'bug', 'flying', 'Butterfly Pokémon', 11, 320, 'It collects honey every day. It rubs honey onto the hairs on its legs to carry it back to its nest.', 11, 'Level 10'),
  (13, 'Weedle', 1, 'bug', 'poison', 'Hairy Bug Pokémon', 3, 32, 'Its poison stinger is very powerful. Its bright-colored body is intended to warn off its enemies.', null, null),
  (14, 'Kakuna', 1, 'bug', 'poison', 'Cocoon Pokémon', 6, 100, 'Although it is a cocoon, it can move a little. It can extend its poison barb if it is attacked.', 13, 'Level 7'),
  (15, 'Beedrill', 1, 'bug', 'poison', 'Poison Bee Pokémon', 10, 295, 'It can take down any opponent with its powerful poison stingers. It sometimes attacks in swarms.', 14, 'Level 10'),
  (16, 'Pidgey', 1, 'normal', 'flying', 'Tiny Bird Pokémon', 3, 18, 'It usually hides in tall grass. Because it dislikes fighting, it protects itself by kicking up sand.', null, null),
  (17, 'Pidgeotto', 1, 'normal', 'flying', 'Bird Pokémon', 11, 300, 'It has outstanding vision. However high it flies, it is able to distinguish the movements of its prey.', 16, 'Level 18'),
  (18, 'Pidgeot', 1, 'normal', 'flying', 'Bird Pokémon', 15, 395, 'Its well-developed chest muscles make it strong enough to whip up a gusty windstorm with just a few flaps.', 17, 'Level 36'),
  (19, 'Rattata', 1, 'normal', null, 'Mouse Pokémon', 3, 35, 'It eats anything. Wherever food is available, it will settle down and produce offspring continuously.', null, null),
  (20, 'Raticate', 1, 'normal', null, 'Mouse Pokémon', 7, 185, 'Gnaws on anything with its tough fangs. It can even topple concrete buildings by gnawing on them.', 19, 'Level 20'),
  (21, 'Spearow', 1, 'normal', 'flying', 'Tiny Bird Pokémon', 3, 20, 'It flaps its short wings to flush out insects from tall grass. It then plucks them with its stubby beak.', null, null),
